  1→/**
  2→ * Authentication utilities for ZakupPro
  3→ *
  4→ * Handles JWT authentication, login/logout, and user session management.
  5→ */
  6→
  7→import { apiFetch } from './api-client';
  8→import { setAuthToken, clearAuthToken, getAuthToken } from './api-client';
  9→import type { LoginRequest, LoginResponse, UserRole } from '@/types/fastapi';
 10→
 11→// =============================================================================
 12→// Constants
 13→// =============================================================================
 14→
 15→const USER_ROLE_KEY = 'user_role';
 16→const USER_ID_KEY = 'user_id';
 17→const USERNAME_KEY = 'username';
 18→
 19→// =============================================================================
 20→// Authentication Functions
 21→// =============================================================================
 22→
 23→/**
 24→ * Authenticate user with username and password
 25→ * Stores JWT token and user info on success
 26→ */
 27→export async function login(username: string, password: string): Promise<{
 28→  success: boolean;
 29→  error?: string;
 30→  role?: UserRole;
 31→}> {
 32→  try {
 33→    const loginData: LoginRequest = { username, password };
 34→
 35→    const result = await apiFetch<LoginResponse>('/api/auth/login', {
 36→      method: 'POST',
 37→      body: loginData,
 38→    });
 39→
 40→    if (result.error) {
 41→      return { success: false, error: result.error.error };
 42→    }
 43→
 44→    const { access_token, role } = result.data!;
 45→
 46→    // Store token and user info
 47→    setAuthToken(access_token);
 48→    setUserSession(username, role);
 49→
 50→    return { success: true, role };
 51→  } catch (error) {
 52→    return {
 53→      success: false,
 54→      error: error instanceof Error ? error.message : 'Login failed',
 55→    };
 56→  }
 57→}
 58→
 59→/**
 60→ * Log out the current user
 61→ * Clears JWT token and user info from localStorage
 62→ */
 63→export function logout(): void {
 64→  clearAuthToken();
 65→  clearUserSession();
 66→}
 67→
 68→/**
 69→ * Check if user is authenticated
 70→ */
 71→export function isAuthenticated(): boolean {
 72→  return getAuthToken() !== null;
 73→}
 74→
 75→/**
 76→ * Get the current user's role
 77→ */
 78→export function getUserRole(): UserRole | null {
 79→  if (typeof window === 'undefined') return null;
 80→  const role = localStorage.getItem(USER_ROLE_KEY) as UserRole | null;
 81→  return role;
 82→}
 83→
 84→/**
 85→ * Get the current user's ID
 86→ */
 87→export function getUserId(): number | null {
 88→  if (typeof window === 'undefined') return null;
 89→  const userId = localStorage.getItem(USER_ID_KEY);
 90→  return userId ? parseInt(userId, 10) : null;
 91→}
 92→
 93→/**
 94→ * Get the current username
 95→ */
 96→export function getUsername(): string | null {
 97→  if (typeof window === 'undefined') return null;
 98→  return localStorage.getItem(USERNAME_KEY);
 99→}
100→
101→// =============================================================================
102→// User Session Helpers (Private)
103→// =============================================================================
104→
105→function setUserSession(username: string, role: UserRole): void {
106→  if (typeof window === 'undefined') return;
107→  localStorage.setItem(USER_ROLE_KEY, role);
108→  localStorage.setItem(USERNAME_KEY, username);
109→  // User ID will be set when we get it from the /users/me endpoint
110→  localStorage.removeItem(USER_ID_KEY);
111→}
112→
113→function clearUserSession(): void {
114→  if (typeof window === 'undefined') return;
115→  localStorage.removeItem(USER_ROLE_KEY);
116→  localStorage.removeItem(USER_ID_KEY);
117→  localStorage.removeItem(USERNAME_KEY);
118→}
