  1→/**
  2→ * FastAPI Client for ZakupPro
  3→ *
  4→ * Provides a typed fetch wrapper for communicating with the FastAPI backend.
  5→ * Handles authentication, error transformation, and standard request/response processing.
  6→ */
  7→
  8→import type { ApiError } from '@/types/fastapi';
  9→
 10→// =============================================================================
 11→// 401 Unauthorized Callback
 12→// =============================================================================
 13→
 14→let _onUnauthorized: (() => void) | null = null
 15→
 16→/**
 17→ * Register a callback invoked when the API returns a 401 response.
 18→ * Used by AuthProvider to auto-logout on token expiration.
 19→ */
 20→export function setOnUnauthorized(callback: (() => void) | null): void {
 21→  _onUnauthorized = callback
 22→}
 23→
 24→// =============================================================================
 25→// Configuration
 26→// =============================================================================
 27→
 28→const FASTAPI_URL = process.env.FASTAPI_URL || 'http://localhost:8000';
 29→
 30→// =============================================================================
 31→// Auth Token Storage (localStorage)
 32→// =============================================================================
 33→
 34→const AUTH_TOKEN_KEY = 'auth_token';
 35→
 36→/**
 37→ * Get the stored JWT token from localStorage
 38→ */
 39→export function getAuthToken(): string | null {
 40→  if (typeof window === 'undefined') return null;
 41→  return localStorage.getItem(AUTH_TOKEN_KEY);
 42→}
 43→
 44→/**
 45→ * Store the JWT token in localStorage
 46→ */
 47→export function setAuthToken(token: string): void {
 48→  if (typeof window === 'undefined') return;
 49→  localStorage.setItem(AUTH_TOKEN_KEY, token);
 50→}
 51→
 52→/**
 53→ * Remove the JWT token from localStorage (logout)
 54→ */
 55→export function clearAuthToken(): void {
 56→  if (typeof window === 'undefined') return;
 57→  localStorage.removeItem(AUTH_TOKEN_KEY);
 58→}
 59→
 60→// =============================================================================
 61→// Types
 62→// =============================================================================
 63→
 64→export interface RequestOptions {
 65→  method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
 66→  body?: unknown;
 67→  headers?: Record<string, string>;
 68→  params?: Record<string, string | number | boolean | undefined>;
 69→}
 70→
 71→export interface ApiResult<T> {
 72→  data: T | null;
 73→  error: ApiError | null;
 74→}
 75→
 76→// =============================================================================
 77→// Error Handling
 78→// =============================================================================
 79→
 80→class ApiError_ extends Error {
 81→  status: number;
 82→  details?: unknown;
 83→
 84→  constructor(message: string, status: number, details?: unknown) {
 85→    super(message);
 86→    this.name = 'ApiError';
 87→    this.status = status;
 88→    this.details = details;
 89→  }
 90→}
 91→
 92→/**
 93→ * Transform FastAPI HTTPException response into standard ApiError format
 94→ */
 95→function transformError(response: Response, body?: unknown): ApiError {
 96→  const status = response.status;
 97→
 98→  // FastAPI HTTPException format: { "detail": string | object }
 99→  let message = 'An error occurred';
100→  let details: unknown;
101→
102→  if (body && typeof body === 'object' && 'detail' in body) {
103→    const detail = body.detail;
104→    if (typeof detail === 'string') {
105→      message = detail;
106→    } else if (detail && typeof detail === 'object') {
107→      message = 'API request failed';
108→      details = detail;
109→    }
110→  } else if (body && typeof body === 'string') {
111→    message = body;
112→  } else {
113→    message = response.statusText || `HTTP ${status}`;
114→  }
115→
116→  return { error: message, details };
117→}
118→
119→/**
120→ * Build query string from params object
121→ */
122→function buildQueryString(params: Record<string, string | number | boolean | undefined>): string {
123→  const searchParams = new URLSearchParams();
124→  for (const [key, value] of Object.entries(params)) {
125→    if (value !== undefined) {
126→      searchParams.append(key, String(value));
127→    }
128→  }
129→  const queryString = searchParams.toString();
130→  return queryString ? `?${queryString}` : '';
131→}
132→
133→// =============================================================================
134→// API Client
135→// =============================================================================
136→
137→/**
138→ * Core fetch function with error handling and authentication
139→ */
140→export async function apiFetch<T>(
141→  endpoint: string,
142→  options: RequestOptions = {}
143→): Promise<ApiResult<T>> {
144→  const url = `${FASTAPI_URL}${endpoint}`;
145→
146→  const headers: Record<string, string> = {
147→    'Content-Type': 'application/json',
148→    ...options.headers,
149→  };
150→
151→  // Add Authorization header from localStorage if available (client-side)
152→  // Allow override via options.headers for server-side or special cases
153→  const hasAuthHeader = Object.keys(options.headers || {}).some(
154→    key => key.toLowerCase() === 'authorization'
155→  );
156→
157→  if (!hasAuthHeader && typeof window !== 'undefined') {
158→    const token = getAuthToken();
159→    if (token) {
160→      headers['Authorization'] = `Bearer ${token}`;
161→    }
162→  }
163→
164→  const config: RequestInit = {
165→    method: options.method || 'GET',
166→    headers,
167→  };
168→
169→  if (options.body) {
170→    config.body = JSON.stringify(options.body);
171→  }
172→
173→  // Add query parameters if provided
174→  let fullUrl = url;
175→  if (options.params) {
176→    fullUrl += buildQueryString(options.params);
177→  }
178→
179→  try {
180→    const response = await fetch(fullUrl, config);
181→
182→    // Handle 204 No Content (successful delete, etc.)
183→    if (response.status === 204) {
184→      return { data: null as T, error: null };
185→    }
186→
187→    // Parse JSON body
188→    let body: unknown;
189→    const contentType = response.headers.get('content-type');
190→    if (contentType?.includes('application/json')) {
191→      body = await response.json();
192→    } else {
193→      body = await response.text();
194→    }
195→
196→    // Check for error status
197→    if (!response.ok) {
198→      // Trigger auto-logout on 401 (token expired/invalid)
199→      if (response.status === 401 && _onUnauthorized) {
200→        _onUnauthorized()
201→      }
202→      const error = transformError(response, body);
203→      return { data: null, error };
204→    }
205→
206→    return { data: body as T, error: null };
207→  } catch (err) {
208→    // Network errors, fetch errors, etc.
209→    const error: ApiError = {
210→      error: err instanceof Error ? err.message : 'Network error',
211→    };
212→    return { data: null, error };
213→  }
214→}
215→
216→// =============================================================================
217→// HTTP Method Helpers
218→// =============================================================================
219→
220→export async function get<T>(
221→  endpoint: string,
222→  params?: Record<string, string | number | boolean | undefined>
223→): Promise<ApiResult<T>> {
224→  return apiFetch<T>(endpoint, { method: 'GET', params });
225→}
226→
227→export async function post<T>(
228→  endpoint: string,
229→  body?: unknown
230→): Promise<ApiResult<T>> {
231→  return apiFetch<T>(endpoint, { method: 'POST', body });
232→}
233→
234→export async function put<T>(
235→  endpoint: string,
236→  body?: unknown
237→): Promise<ApiResult<T>> {
238→  return apiFetch<T>(endpoint, { method: 'PUT', body });
239→}
240→
241→export async function patch<T>(
242→  endpoint: string,
243→  body?: unknown
244→): Promise<ApiResult<T>> {
245→  return apiFetch<T>(endpoint, { method: 'PATCH', body });
246→}
247→
248→export async function del<T>(
249→  endpoint: string
250→): Promise<ApiResult<T>> {
251→  return apiFetch<T>(endpoint, { method: 'DELETE' });
252→}
253→
254→// =============================================================================
255→// Convenience Functions
256→// =============================================================================
257→
258→/**
259→ * Throws an error if the API result contains an error
260→ * Useful for handling API responses in a try/catch pattern
261→ */
262→export function throwErrorOnError<T>(result: ApiResult<T>): T {
263→  if (result.error) {
264→    throw new ApiError_(
265→      result.error.error,
266→      0, // Status not available in ApiResult
267→      result.error.details
268→    );
269→  }
270→  return result.data as T;
271→}
272→
273→/**
274→ * Check if the API result is successful
275→ */
276→export function isSuccess<T>(result: ApiResult<T>): result is ApiResult<T> & { data: T } {
277→  return result.error === null && result.data !== null;
278→}
279→
280→/**
281→ * Check if the API result failed
282→ */
283→export function isFailure<T>(result: ApiResult<T>): result is ApiResult<T> & { error: ApiError } {
284→  return result.error !== null;
285→}
286→
287→// =============================================================================
288→// Export default client object
289→// =============================================================================
290→
291→export const apiClient = {
292→  get,
293→  post,
294→  put,
295→  patch,
296→  delete: del,
297→  fetch: apiFetch,
298→};
299→
300→export default apiClient;
